    if 'Metadata/model_settings.config' in names:
        ms=z.read('Metadata/model_settings.config').decode('utf8','replace')
        out['extrudersUsed']=sorted(set(re.findall(r'key="extruder" value="(\d+)"',ms)))
        out['layerRanges']='layer_height_range' in ms or '<range' in ms
        out['plates']=ms.count('<plate>')
    return out
